                        "courseId": COURSE, "courseTitle": "Runtime Security", "revision": "rev-1",
                        "status": "in_progress", "draftVersion": 2, "draft": {}, "result": {}, "conflicts": [],
                        "locked": false, "lockReason": null, "createdAt": in_secs(-60), "mode": "triage",
